export async function submitOrder(input: {sku:string}, headers: Record<string,string>) {
  const res = await fetch('/orders', {method:'POST', headers, body:JSON.stringify(input)});
  if (!res.ok) throw new Error('Order failed');
  return res.json();
}
export const onSave = () => submitOrder({sku:'A'}, {'X-Trace':'t'});

export const checkoutValid = (age: number) => age >= 18;
export const eventValid = (age: number) => age >= 18;
export function checkout(age:number) { return checkoutValid(age); }
export function registerEvent(age:number) { return eventValid(age); }

export async function buy(sku: string) {
  return navigator.locks.request('purchase', () => fetch('/buy', {
    method:'POST', body: JSON.stringify({sku})
  }));
}
